//! In-memory rolling market state and score recomputation.
use std::collections::{HashMap,VecDeque};use std::sync::Mutex;use score_engine::{ScoreInput,ScoreWeights};use shared::{Candle,FundingRate,OpenInterest,OrderBookSnapshot,Score};const CANDLE_HISTORY:usize=60;
struct SymbolState{candles:VecDeque<Candle>,order_book:Option<OrderBookSnapshot>,funding_rate:Option<FundingRate>,open_interest:VecDeque<OpenInterest>,latest_score:Option<Score>}
impl SymbolState{fn new()->Self{Self{candles:VecDeque::with_capacity(CANDLE_HISTORY),order_book:None,funding_rate:None,open_interest:VecDeque::with_capacity(2),latest_score:None}}fn recompute(&mut self,symbol:&str,weights:&ScoreWeights)->Option<Score>{if self.candles.is_empty(){return None}let order_book=self.order_book.clone().unwrap_or_else(||OrderBookSnapshot{symbol:symbol.into(),timestamp:0,bids:vec![],asks:vec![]});let funding_rate=self.funding_rate.clone().unwrap_or_else(||FundingRate{symbol:symbol.into(),timestamp:0,rate:0.0});let input=ScoreInput{candles:self.candles.iter().cloned().collect(),order_book,funding_rate};let score=score_engine::calculate(&input,weights);self.latest_score=Some(score.clone());Some(score)}}
pub struct MarketState{symbols:Mutex<HashMap<String,SymbolState>>,weights:ScoreWeights}
impl MarketState{pub fn new(weights:ScoreWeights)->Self{Self{symbols:Mutex::new(HashMap::new()),weights}}pub fn latest_score(&self,symbol:&str)->Option<Score>{self.symbols.lock().expect("market state lock poisoned").get(symbol).and_then(|s|s.latest_score.clone())}pub fn ingest_candle(&self,candle:Candle)->Option<Score>{let mut symbols=self.symbols.lock().expect("market state lock poisoned");let state=symbols.entry(candle.symbol.clone()).or_insert_with(SymbolState::new);if let Some(last)=state.candles.back_mut(){if last.interval==candle.interval&&last.open_time==candle.open_time{*last=candle.clone();return state.recompute(&candle.symbol,&self.weights)}}state.candles.push_back(candle.clone());if state.candles.len()>CANDLE_HISTORY{state.candles.pop_front();}state.recompute(&candle.symbol,&self.weights)}pub fn ingest_order_book(&self,snapshot:OrderBookSnapshot)->Option<Score>{let mut symbols=self.symbols.lock().expect("market state lock poisoned");let state=symbols.entry(snapshot.symbol.clone()).or_insert_with(SymbolState::new);let symbol=snapshot.symbol.clone();state.order_book=Some(snapshot);state.recompute(&symbol,&self.weights)}pub fn ingest_funding_rate(&self,rate:FundingRate)->Option<Score>{let mut symbols=self.symbols.lock().expect("market state lock poisoned");let state=symbols.entry(rate.symbol.clone()).or_insert_with(SymbolState::new);let symbol=rate.symbol.clone();state.funding_rate=Some(rate);state.recompute(&symbol,&self.weights)}pub fn ingest_open_interest(&self,oi:OpenInterest)->Option<Score>{let mut symbols=self.symbols.lock().expect("market state lock poisoned");let state=symbols.entry(oi.symbol.clone()).or_insert_with(SymbolState::new);let symbol=oi.symbol.clone();state.open_interest.push_back(oi);while state.open_interest.len()>2{state.open_interest.pop_front();}state.recompute(&symbol,&self.weights)}pub fn latest_derivatives(&self,symbol:&str)->Option<score_engine::DerivativesResult>{let symbols=self.symbols.lock().ok()?;let state=symbols.get(symbol)?;let funding=state.funding_rate.as_ref()?;let current=state.open_interest.back();let previous=if state.open_interest.len()>=2{state.open_interest.front()}else{None};let price_change=if state.candles.len()>=2{let a=&state.candles[state.candles.len()-2];let b=state.candles.back()?;if a.close!=0.0{(b.close/a.close-1.0)*100.0}else{0.0}}else{0.0};Some(score_engine::derivatives(previous,current,funding,price_change))}pub fn intelligence(&self,symbol:&str)->Option<score_engine::IntelligenceSnapshot>{let score=self.latest_score(symbol)?;let derivatives=self.latest_derivatives(symbol);Some(score_engine::intelligence_snapshot(&score,derivatives.as_ref()))}}
#[cfg(test)]mod tests{use super::*;fn candle(symbol:&str,t:i64)->Candle{Candle{symbol:symbol.into(),interval:"1m".into(),open_time:t,close_time:t+60000,open:100.0,high:100.0,low:100.0,close:100.0,volume:100.0}}#[test]fn scores_after_first_candle(){let s=MarketState::new(ScoreWeights::default());s.ingest_candle(candle("BTCUSDT",0));assert!(s.latest_score("BTCUSDT").is_some());}#[test]fn keeps_two_oi_points(){let s=MarketState::new(ScoreWeights::default());for i in 0..3{s.ingest_open_interest(OpenInterest{symbol:"BTCUSDT".into(),timestamp:i,value:100.0+i as f64});}let x=s.symbols.lock().unwrap();assert_eq!(x.get("BTCUSDT").unwrap().open_interest.len(),2);}#[test]fn builds_intelligence_snapshot(){let s=MarketState::new(ScoreWeights::default());s.ingest_candle(candle("BTCUSDT",0));assert!(s.intelligence("BTCUSDT").is_some());}}
